"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["96371"],{41767(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.notas_do_enem.oferta_de_inscricao_fora_do_edital","status":422,"titulo":"H\xe1 inscri\xe7\xe3o que concorre a um curso que n\xe3o est\xe1 no edital divulgado"},"descricao":{"codigo":"uniplus.selecao.notas_do_enem.oferta_de_inscricao_fora_do_edital","requisitos":["UNI-REQ-0174"],"oQueAconteceu":["A nota da etapa do ENEM \xe9 calculada para cada curso que a inscri\xe7\xe3o concorre, com os pesos do grupo de \xe1rea desse curso no edital divulgado (UNI-REQ-0174). Alguma inscri\xe7\xe3o enviada da edi\xe7\xe3o concorre, em primeira ou segunda op\xe7\xe3o, a um curso que n\xe3o est\xe1 no edital divulgado, em geral porque uma retifica\xe7\xe3o o retirou. Sem o curso no edital n\xe3o h\xe1 peso para calcular a nota, ent\xe3o a importa\xe7\xe3o foi recusada inteira e nenhum lote foi gravado. A mensagem diz quantas inscri\xe7\xf5es est\xe3o nessa situa\xe7\xe3o, sem identific\xe1-las."],"comoResolver":["Confira a retifica\xe7\xe3o que retirou o curso. Recoloque o mesmo curso no edital por uma nova retifica\xe7\xe3o, divulgue-a e importe o arquivo de novo: as inscri\xe7\xf5es voltam a ter o curso com peso e a importa\xe7\xe3o \xe9 aceita."],"ondeAparece":["Importa\xe7\xe3o do arquivo de retorno do INEP"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Notas do enem"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);